export function agentMuxCliArguments(argv: readonly string[]): { args: string[]; endpoint?: string; sourceHost?: string } {
  const args = [...argv]
  let endpoint: string | undefined, sourceHost: string | undefined
  while (['--endpoint', '--source-host'].some(name => args[0] === name || args[0]?.startsWith(name + '='))) {
    const option = args.shift()!
    const name = option.split('=', 1)[0]!, input = option === name ? args.shift() : option.slice(name.length + 1)
    if (!input?.length || option === name && input.startsWith('--')) invalid(`${name} requires a value; use ${name}=VALUE for option-looking data.`)
    if (name === '--endpoint') { if (endpoint !== undefined) invalid('Duplicate option: --endpoint'); endpoint = input }
    else { if (sourceHost !== undefined) invalid('Duplicate option: --source-host'); sourceHost = input }
  }
  if (endpoint !== undefined && sourceHost !== undefined) invalid('--endpoint and --source-host are mutually exclusive.')
  return { args, ...(endpoint === undefined ? {} : { endpoint }), ...(sourceHost === undefined ? {} : { sourceHost }) }
}
export function agentMuxCliMatch(args: readonly string[]): { command: AgentMuxCliCommand; tail: string[] } | null {
  let selected: AgentMuxCliCommand | undefined
  let length = 0
  for (const entry of AGENTMUX_CLI_COMMANDS) {
    const path = entry.method.split('.')
    if (path.length > length && path.every((part, index) => args[index] === part)) {
      selected = entry
      length = path.length
    }
  }
  return selected ? { command: selected, tail: args.slice(length) } : null
}
export async function agentMuxCliRequestsHelp(command: AgentMuxCliCommand, args: readonly string[]): Promise<boolean> {
  // Help is a syntax-only invocation. A data-bearing request cannot hide extra
  // arguments behind a later --help; positional IDs and carrier paths stay literal.
  if (args.length !== 1 || args[0] !== '--help' && args[0] !== '-h') return false
  if (command.positionalData !== 1) return true
  // These single-positional branches validate syntax without carrier IO. Reuse
  // their actual grammar: a positional slot alone need not be a complete request.
  try { await command.parse(args); return false }
  catch (error) {
    if (error instanceof AgentMuxError && error.code === 'INVALID_CLI_ARGUMENT') return true
    throw error
  }
}
export async function parseAgentMuxCliInvocation(argv: readonly string[]): Promise<AgentMuxCliInvocation> {
  const { args, endpoint, sourceHost } = agentMuxCliArguments(argv)
  const match = agentMuxCliMatch(args)
  if (!match) invalid('Unknown command. Run amux --help.')
  const command = match!.command.rpcMethod ? { ...match!.command, method: match!.command.rpcMethod } : match!.command
  let tail = match!.tail, output: string | undefined
  if (match!.command.method === 'browser.capture' || ['app.capture', 'app.record.read', 'system.metrics.host-profile.capture', 'system.metrics.profile.capture', 'system.metrics.trace.capture', 'system.metrics.allocations.capture', 'system.metrics.scene.capture', 'system.metrics.scene.inspect'].includes(command.method)) {
    output = value(flags(tail, command.flags!), '--output')
    if (output !== undefined && (!output || output === '-')) invalid(command.method === 'system.metrics.profile.capture'
      ? '--output requires a named new local cpuprofile file.' : '--output requires a named new local diagnostic file.')
  }
  if (command.documentOutput && tail.length !== 1) {
    tail = expandCliOptionAssignments(tail, command.positionalData ?? 0)
    if (tail.length !== 3 || tail[1] !== '--output' || !tail[2]?.length || tail[2] === '-') invalid('Use inspect <id> --output FILE; output creates a new file and never overwrites an existing file.')
    output = tail[2]; tail = tail.slice(0, 1)
  }
  const hostingRuntimeId = isConnectionReceiverMethod(command.method) ? id(flags(tail, command.flags!), '--runtime', true) : undefined
  return { command, params: await match!.command.parse(tail), ...(hostingRuntimeId === undefined ? {} : { hostingRuntimeId }), ...(output === undefined ? {} : { output }), ...(endpoint === undefined ? {} : { endpoint }), ...(sourceHost === undefined ? {} : { sourceHost }) }
}
